\Function{AlphaBetaMax}{Node, $\alpha, \beta$}
    \If{DepthLimitReached(Node)}
        \State \Return Rating(Node)
    \EndIf
    \State NewNodes $\gets$ Successors(Node)
    \While{NewNodes $\neq \varnothing$}
