\begin{verbatim}
void hill_climbing(tsp_instance *t, tsp_solution *s) {
    double cost;      /* best cost so far */
    double delta;     /* swap cost */
    int i, j;         /* counters */
    bool stuck;       /* did I get a better solution? */
    initialize_solution(t->n, s);
    random_solution(s);
    cost = solution_cost(s, t);
    do {
        stuck = true;
        for (i = 1; i < t->n; i++) {
            for (j = i + 1; j <= t->n; j++) {
                delta = transition(s, t, i, j);
                if (delta < 0) {
                    stuck = false;
                    cost = cost + delta;
                } else {
                    transition(s, t, j, i);
                }
                solution_count_update(s, t);
            }
        }
    } while (stuck);
}
\end{verbatim}

When does local search do well?
\begin{itemize}
    \item \textit{When there is great coherence in the solution space} -- Hill climbing is at its best when the solution space is \textit{convex}. In other words, it consists of exactly one hill. No matter where you start on the hill, there is always a direction to walk up until you are at the absolute global maximum.
\end{itemize}

