4 & 4
\end{array}\right]\left[\begin{array}{ll}
1 & 0 \\
0 & 2
\end{array}\right]\right)\left[\begin{array}{ll}
3 & 2 \\
1 & 0
\end{array}\right]=\left[\begin{array}{ll}
